CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', invite_code uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_game_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_game_admin());
CREATE POLICY profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.participant_progress (user_id uuid PRIMARY KEY, intro jsonb NOT NULL DEFAULT '{}'::jsonb, challenge jsonb NOT NULL DEFAULT '{}'::jsonb, intro_draft jsonb, first_seen timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), current_path text NOT NULL DEFAULT '/', completed_cards integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.participant_progress TO authenticated; GRANT ALL ON public.participant_progress TO service_role;
ALTER TABLE public.participant_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_read ON public.participant_progress FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_game_admin());
CREATE TABLE public.points_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, event_key text NOT NULL, amount integer NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_key));
GRANT SELECT ON public.points_ledger TO authenticated; GRANT ALL ON public.points_ledger TO service_role;
ALTER TABLE public.points_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY points_read ON public.points_ledger FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_game_admin());
CREATE TABLE public.story_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, url text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, UNIQUE(user_id,url));
GRANT SELECT,INSERT ON public.story_submissions TO authenticated; GRANT ALL ON public.story_submissions TO service_role;
ALTER TABLE public.story_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY stories_read ON public.story_submissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_game_admin());
CREATE POLICY stories_insert ON public.story_submissions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND reviewed_at IS NULL AND url ~ '^https://');
CREATE TABLE public.referrals (invited_user uuid PRIMARY KEY, inviter_user uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.referrals TO authenticated; GRANT ALL ON public.referrals TO service_role;
ALTER TABLE public.referrals ENABLE ROW LEVEL SECURITY;
CREATE POLICY referral_read ON public.referrals FOR SELECT TO authenticated USING(inviter_user=auth.uid() OR public.is_game_admin());
CREATE TABLE public.telegram_links (user_id uuid PRIMARY KEY, chat_id bigint UNIQUE, link_code uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, enabled boolean NOT NULL DEFAULT false, last_notified date);
GRANT SELECT ON public.telegram_links TO authenticated; GRANT ALL ON public.telegram_links TO service_role;
ALTER TABLE public.telegram_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY telegram_read ON public.telegram_links FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.setup_game_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name','')) ON CONFLICT(id) DO NOTHING; IF lower(NEW.email)='rapportower@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER game_account_created AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.setup_game_account();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'full_name','') FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin' FROM auth.users WHERE lower(email)='rapportower@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT DO NOTHING;
CREATE FUNCTION public.sync_game_progress(p_intro jsonb,p_challenge jsonb,p_draft jsonb,p_path text,p_offset integer DEFAULT 0) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); old_data jsonb; start_time timestamptz; prior_start timestamptz; day_start timestamptz; done_time timestamptz; d integer; entry jsonb; season_key text; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF jsonb_typeof(p_intro) <> 'object' OR jsonb_typeof(p_challenge) <> 'object' OR octet_length(p_intro::text)+octet_length(p_challenge::text)>1000000 THEN RAISE EXCEPTION 'Invalid progress'; END IF; SELECT challenge INTO old_data FROM public.participant_progress WHERE user_id=uid FOR UPDATE; BEGIN start_time:=(p_challenge->>'startedAt')::timestamptz; prior_start:=(old_data->>'startedAt')::timestamptz; EXCEPTION WHEN others THEN RAISE EXCEPTION 'Invalid date'; END; IF prior_start IS NOT NULL AND start_time IS DISTINCT FROM prior_start THEN start_time:=prior_start; p_challenge:=jsonb_set(p_challenge,'{startedAt}',to_jsonb(prior_start)); END IF; IF start_time>now()+interval '5 minutes' THEN RAISE EXCEPTION 'Invalid start'; END IF; INSERT INTO public.participant_progress(user_id,intro,challenge,intro_draft,last_seen,current_path,completed_cards) VALUES(uid,p_intro,p_challenge,p_draft,now(),left(p_path,100),coalesce(jsonb_object_length_safe(p_intro->'days'),0)+coalesce(jsonb_object_length_safe(p_challenge->'days'),0)) ON CONFLICT(user_id) DO UPDATE SET intro=excluded.intro,challenge=excluded.challenge,intro_draft=excluded.intro_draft,last_seen=now(),current_path=excluded.current_path,completed_cards=excluded.completed_cards; UPDATE public.profiles SET display_name=left(coalesce(p_intro->>'name',p_challenge->>'name',display_name),100) WHERE id=uid; IF start_time IS NOT NULL THEN season_key:=start_time::date::text; FOR d IN 1..7 LOOP day_start:=date_trunc('day',start_time-make_interval(mins=>greatest(-840,least(840,p_offset))))+make_interval(days=>d-1)+make_interval(mins=>greatest(-840,least(840,p_offset))); entry:=p_challenge->'days'->d::text; done_time:=NULL; IF entry IS NOT NULL THEN BEGIN done_time:=(entry->>'doneAt')::timestamptz; EXCEPTION WHEN others THEN done_time:=NULL; END; END IF; IF now()>=day_start+interval '1 day' AND (done_time IS NULL OR done_time>=day_start+interval '1 day') THEN INSERT INTO public.points_ledger(user_id,event_key,amount,reason) VALUES(uid,season_key||':missed:'||d,-50,'Пропуск дня '||d) ON CONFLICT DO NOTHING; END IF; IF entry IS NOT NULL AND done_time>=day_start AND done_time<=now()+interval '5 minutes' AND now()>=day_start AND entry->>'resource' IS NOT NULL THEN INSERT INTO public.points_ledger(user_id,event_key,amount,reason) VALUES(uid,season_key||':day:'||d,50,'Завершён день '||d) ON CONFLICT DO NOTHING; END IF; END LOOP; END IF; END $$;
CREATE FUNCTION public.jsonb_object_length_safe(value jsonb) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT count(*)::integer FROM jsonb_object_keys(CASE WHEN jsonb_typeof(value)='object' THEN value ELSE '{}'::jsonb END) $$;
CREATE FUNCTION public.claim_game_referral(p_code uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inviter uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT id INTO inviter FROM public.profiles WHERE invite_code=p_code; IF inviter IS NULL OR inviter=auth.uid() THEN RETURN; END IF; INSERT INTO public.referrals(invited_user,inviter_user) VALUES(auth.uid(),inviter) ON CONFLICT DO NOTHING; IF FOUND THEN INSERT INTO public.points_ledger(user_id,event_key,amount,reason) VALUES(inviter,'referral:'||auth.uid(),100,'Приглашена участница') ON CONFLICT DO NOTHING; END IF; END $$;
CREATE FUNCTION public.review_game_story(p_id uuid,p_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner_id uuid; BEGIN IF NOT public.is_game_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.story_submissions SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now() WHERE id=p_id AND status='pending' RETURNING user_id INTO owner_id; IF owner_id IS NOT NULL AND p_approve THEN INSERT INTO public.points_ledger(user_id,event_key,amount,reason) VALUES(owner_id,'story:'||p_id,50,'Подтверждённая история') ON CONFLICT DO NOTHING; END IF; END $$;
CREATE FUNCTION public.prepare_telegram_link() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.telegram_links(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; SELECT link_code INTO code FROM public.telegram_links WHERE user_id=auth.uid(); RETURN code; END $$;
REVOKE ALL ON FUNCTION public.sync_game_progress(jsonb,jsonb,jsonb,text,integer), public.claim_game_referral(uuid), public.review_game_story(uuid,boolean),public.prepare_telegram_link() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sync_game_progress(jsonb,jsonb,jsonb,text,integer), public.claim_game_referral(uuid), public.review_game_story(uuid,boolean),public.prepare_telegram_link() TO authenticated;
REVOKE ALL ON FUNCTION public.setup_game_account() FROM PUBLIC,anon,authenticated;